import{_ as o,o as t,c as a,a4 as s}from"./chunks/framework.vNSRaLQv.js";const u=JSON.parse('{"title":"DeepSeek Web Agent Proxy - 工具调用解析修复记录","description":"","frontmatter":{"title":"DeepSeek Web Agent Proxy - 工具调用解析修复记录","date":"2026-06-26T00:00:00.000Z"},"headers":[],"relativePath":"posts/proxy-tool-call-fix.md","filePath":"posts/proxy-tool-call-fix.md"}'),i={name:"posts/proxy-tool-call-fix.md"};function l(n,e,c,d,r,h){return t(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="deepseek-web-agent-proxy-工具调用解析修复记录" tabindex="-1">DeepSeek Web Agent Proxy - 工具调用解析修复记录 <a class="header-anchor" href="#deepseek-web-agent-proxy-工具调用解析修复记录" aria-label="Permalink to &quot;DeepSeek Web Agent Proxy - 工具调用解析修复记录&quot;">​</a></h1><h2 id="问题现象" tabindex="-1">问题现象 <a class="header-anchor" href="#问题现象" aria-label="Permalink to &quot;问题现象&quot;">​</a></h2><p>OpenCode 通过 cc-switch → proxy → Qwen 后端发送工具调用请求时，模型输出了正确的工具调用文本（如 <code>工具 Write\\nfile_path=&quot;...&quot;\\ncontent=&quot;...&quot;</code>），但 OpenCode 报错：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>The model&#39;s tool call could not be parsed (retry also failed).</span></span></code></pre></div><p>模型的工具调用文本被当作普通 content 原样返回，没有被解析成 OpenAI <code>tool_calls</code> 格式。</p><h2 id="排查过程" tabindex="-1">排查过程 <a class="header-anchor" href="#排查过程" aria-label="Permalink to &quot;排查过程&quot;">​</a></h2><h3 id="_1-检查正则表达式" tabindex="-1">1. 检查正则表达式 <a class="header-anchor" href="#_1-检查正则表达式" aria-label="Permalink to &quot;1. 检查正则表达式&quot;">​</a></h3><p><code>tool_format.py</code> 中的 <code>TOOL_BLOCK_RE</code> 正则本身能正确匹配模型输出的工具块文本。直接调用 <code>parse_tool_blocks()</code> 可以解析出 <code>{name, arguments}</code>。</p><h3 id="_2-发现-codec-id-跳过逻辑" tabindex="-1">2. 发现 codec_id 跳过逻辑 <a class="header-anchor" href="#_2-发现-codec-id-跳过逻辑" aria-label="Permalink to &quot;2. 发现 codec_id 跳过逻辑&quot;">​</a></h3><p><code>handler.py</code> 的 <code>_detect_tool_blocks()</code> 函数有一个关键判断：</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span style="--shiki-light:#1E754F;--shiki-dark:#4D9375;">if</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;"> tool_codec_id </span><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676;">!=</span><span style="--shiki-light:#B5695977;--shiki-dark:#C98A7D77;"> &quot;</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;">deepseek_natural</span><span style="--shiki-light:#B5695977;--shiki-dark:#C98A7D77;">&quot;</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">:</span></span>
<span class="line"><span style="--shiki-light:#1E754F;--shiki-dark:#4D9375;">    return</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;"> text</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">,</span><span style="--shiki-light:#999999;--shiki-dark:#666666;"> []</span><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;">  # 直接跳过，不解析！</span></span></code></pre></div><p>Qwen 后端设置 <code>_tool_codec_id = &quot;openai_json&quot;</code>，导致工具块文本<strong>从未被解析</strong>。</p><h3 id="_3-发现流式-content-泄漏" tabindex="-1">3. 发现流式 content 泄漏 <a class="header-anchor" href="#_3-发现流式-content-泄漏" aria-label="Permalink to &quot;3. 发现流式 content 泄漏&quot;">​</a></h3><p>即使修复了 codec_id 跳过逻辑，流式路径还有一个问题：当 Qwen 后端同时返回结构化 <code>tool_call</code> 事件和 content 中的工具块文本时，原代码在 <code>tool_calls_acc</code> 非空时直接把原始 content 发出去，没有清理其中的工具块文本。</p><h3 id="_4-发现转义函数过度处理" tabindex="-1">4. 发现转义函数过度处理 <a class="header-anchor" href="#_4-发现转义函数过度处理" aria-label="Permalink to &quot;4. 发现转义函数过度处理&quot;">​</a></h3><p><code>_unescape()</code> 函数将 <code>\\t</code> 转成 tab、<code>\\n</code> 转成换行。但 Windows 路径中 <code>\\test.txt</code> 的 <code>\\t</code> 是路径分隔符，不是转义序列。这导致路径被破坏。</p><h3 id="_5-发现-sse-chunk-格式不对" tabindex="-1">5. 发现 SSE chunk 格式不对 <a class="header-anchor" href="#_5-发现-sse-chunk-格式不对" aria-label="Permalink to &quot;5. 发现 SSE chunk 格式不对&quot;">​</a></h3><p>将整个 <code>tool_call</code>（name + arguments）放在一个 SSE chunk 里发送。OpenAI 标准流式格式是分步的：</p><ul><li>chunk1: <code>tool_calls[0] = {id, type, function: {name, arguments: &quot;&quot;}}</code></li><li>chunk2: <code>tool_calls[0] = {function: {arguments: &quot;&lt;完整 JSON&gt;&quot;}}</code></li></ul><h2 id="修复内容" tabindex="-1">修复内容 <a class="header-anchor" href="#修复内容" aria-label="Permalink to &quot;修复内容&quot;">​</a></h2><h3 id="handler-py" tabindex="-1">handler.py <a class="header-anchor" href="#handler-py" aria-label="Permalink to &quot;handler.py&quot;">​</a></h3><ol><li><strong><code>_detect_tool_blocks()</code></strong> — 移除 <code>tool_codec_id</code> 跳过逻辑，始终尝试解析工具块</li><li><strong><code>stream_response()</code></strong> — 始终调用 <code>_detect_tool_blocks()</code> 清理 content 中的工具块文本</li><li><strong><code>collect_response()</code></strong> — 同上，非流式路径也始终解析</li><li><strong>新增 <code>_stream_tool_call_chunks()</code></strong> — 将单个 tool_call 拆成 OpenAI 标准的增量 SSE chunks</li></ol><h3 id="tool-format-py" tabindex="-1">tool_format.py <a class="header-anchor" href="#tool-format-py" aria-label="Permalink to &quot;tool_format.py&quot;">​</a></h3><ol start="5"><li><strong><code>_unescape()</code></strong> — 只处理 <code>\\&quot;</code> 和 <code>\\\\</code>，不再处理 <code>\\n</code> <code>\\t</code>，避免破坏 Windows 路径</li></ol><h2 id="最终-sse-输出格式" tabindex="-1">最终 SSE 输出格式 <a class="header-anchor" href="#最终-sse-输出格式" aria-label="Permalink to &quot;最终 SSE 输出格式&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>data: {&quot;choices&quot;: [{&quot;delta&quot;: {&quot;role&quot;: &quot;assistant&quot;, &quot;content&quot;: &quot;&quot;}}]}</span></span>
<span class="line"><span>data: {&quot;choices&quot;: [{&quot;delta&quot;: {&quot;tool_calls&quot;: [{&quot;index&quot;: 0, &quot;id&quot;: &quot;call_xxx&quot;, &quot;type&quot;: &quot;function&quot;, &quot;function&quot;: {&quot;name&quot;: &quot;Write&quot;, &quot;arguments&quot;: &quot;&quot;}}]}}]}</span></span>
<span class="line"><span>data: {&quot;choices&quot;: [{&quot;delta&quot;: {&quot;tool_calls&quot;: [{&quot;index&quot;: 0, &quot;function&quot;: {&quot;arguments&quot;: &quot;{\\&quot;file_path\\&quot;: \\&quot;C:\\\\\\\\Users\\\\\\\\...\\&quot;, \\&quot;content\\&quot;: \\&quot;hello\\&quot;}&quot;}}]}}]}</span></span>
<span class="line"><span>data: {&quot;choices&quot;: [{&quot;delta&quot;: {}, &quot;finish_reason&quot;: &quot;tool_calls&quot;}], &quot;usage&quot;: {...}}</span></span>
<span class="line"><span>data: [DONE]</span></span></code></pre></div><h2 id="涉及文件" tabindex="-1">涉及文件 <a class="header-anchor" href="#涉及文件" aria-label="Permalink to &quot;涉及文件&quot;">​</a></h2><ul><li><code>proxy/handler.py</code> — 流式/非流式响应编排</li><li><code>proxy/tool_format.py</code> — 工具块正则解析</li><li><code>proxy/backends/qwen_web/__init__.py</code> — Qwen 后端（<code>_tool_codec_id = &quot;openai_json&quot;</code>）</li><li><code>proxy/backends/qwen_web/qwen_api.py</code> — Qwen API 调用（yield content + tool_call 事件）</li></ul>`,28)])])}const q=o(i,[["render",l]]);export{u as __pageData,q as default};
